p_relative_url.value:
@concat(
  pipeline().parameters.p_relative_url_prefix,
  string(add(
    pipeline().parameters.p_start_year,
    mul(item(), pipeline().parameters.p_step_years)
  )),
  if(
    empty(pipeline().parameters.p_snapshot_month),
    '',
    concat('-', pipeline().parameters.p_snapshot_month)
  ),
  pipeline().parameters.p_file_name_extension
)

p_file_name.value:
@concat(
  pipeline().parameters.p_file_name_prefix,
  string(add(
    pipeline().parameters.p_start_year,
    mul(item(), pipeline().parameters.p_step_years)
  )),
  if(
    empty(pipeline().parameters.p_snapshot_month),
    '',
    concat('-', pipeline().parameters.p_snapshot_month)
  ),
  pipeline().parameters.p_file_name_extension
)
